type BrainCompiledEvidence = {
  id: string;
  provider: string;
  route: string;
  page: string | null;
  source: string | null;
  locator: Record<string, unknown>;
  content: string;
  roles: string[];
  authoredState: string;
  derivedFlags: string[];
  authoritySignals: string[];
  selectionReasons: string[];
  byteCost: number;
  truncated: boolean;
  atomic: boolean;
};

type BrainCompilerOmission = {
  candidateId: string;
  reason: string;
  estimatedBytes: number | null;
};

type BrainCompilerStop = {
  reason: string;
  sufficient: boolean;
  detail: string;
};

type BrainCompilerDiagnostic = {
  code: string;
  message: string;
  provider: string | null;
  details: Record<string, unknown>;
};

type BrainCompilerReporting = {
  omissions: { total: number; returned: number };
  diagnostics: { total: number; returned: number };
};

type BrainRetrievalResult = {
  contractVersion: "1" | "3";
  wiki: {
    alias: string;
    schemaVersion: string;
    runtimeContract: string;
  };
  query: {
    question: string;
    shapes: string[];
    stateView: string;
    resolvedSeeds: string[];
    projectResolution?: BrainProjectResolution;
    temporal?: TemporalQuery;
  };
  evidence: BrainCompiledEvidence[];
  omissions: BrainCompilerOmission[];
  coverage: BrainCompilerCoverage;
  budget: BrainCompilerBudget;
  stop: BrainCompilerStop;
  continuation: Record<string, unknown> | null;
  diagnostics: BrainCompilerDiagnostic[];
  reporting: BrainCompilerReporting;
  selectedPages: string[];
  evidenceCount: number;
  candidateCount: number;
};

